steps.checkScript:
[ -s alle.txt ] || { echo "alle.txt fehlt oder ist leer."; exit 1; }
grep -q '\.versteckt' alle.txt || { echo "Die versteckten Dateien fehlen (z. B. .versteckt)."; exit 1; }
grep -Eq '^[-d][rwx-]{9}' alle.txt || { echo "Das ist nicht die lange Form (Rechte, Besitzer, Grösse …)."; exit 1; }
echo "Alles da."

for f in foo.txt bar.txt; do
  [ -f "$f" ] || { echo "$f fehlt."; exit 1; }
  [ "$(cat "$f")" = "hello world" ] || { echo "$f muss genau 'hello world' enthalten."; exit 1; }
done
echo "Beide Dateien passen."

cd aufgabe14 || { echo "Der Ordner aufgabe14 fehlt."; exit 1; }
[ -e foo ] && { echo "foo gibt es noch – sie soll umbenannt werden."; exit 1; }
for f in bar foobar; do
  [ -f "$f" ] || { echo "aufgabe14/$f fehlt."; exit 1; }
  [ "$(cat "$f")" = "Inhalt von foo" ] || { echo "aufgabe14/$f hat nicht den Inhalt der ursprünglichen foo."; exit 1; }
done
[ -f befehle.txt ] || { echo "aufgabe14/befehle.txt fehlt."; exit 1; }
grep -Eq '(^|[[:space:]])mv[[:space:]]' befehle.txt || { echo "In befehle.txt fehlt der Befehl zum Umbenennen."; exit 1; }
grep -Eq '(^|[[:space:]])cp[[:space:]]' befehle.txt || { echo "In befehle.txt fehlt der Befehl zum Kopieren."; exit 1; }
echo "Sauber gemacht."

bad() {
  out=$(timeout 5 bash ./rechner.sh "$@" 2>&1); rc=$?
  if [ "$rc" -eq 0 ]; then echo "'./rechner.sh $*' sollte mit einem Fehler (Exit-Code ≠ 0) enden."; exit 1; fi
  if [ -z "$out" ]; then echo "'./rechner.sh $*' soll eine Fehlermeldung ausgeben."; exit 1; fi
}
bad
bad 10
bad abc 5
bad 10 x
bad 10 0
out=$(timeout 5 bash ./rechner.sh 10 5 2>&1) || { echo "Mit gültigen Zahlen darf kein Fehler kommen."; exit 1; }
echo "$out" | grep -Eq 'Summe:[[:space:]]*15' || { echo "Die normale Berechnung funktioniert nicht mehr."; exit 1; }
echo "Fehler werden sauber abgefangen."

out=$(timeout 5 bash ./count_files.sh ./testdaten .txt 2>&1)
echo "$out" | grep -Eq 'Dateien:[[:space:]]*5([^0-9]|$)' || { echo "Mit .txt erwartet: Dateien: 5. Ausgabe: $out"; exit 1; }
out=$(timeout 5 bash ./count_files.sh ./testdaten .log 2>&1)
echo "$out" | grep -Eq 'Dateien:[[:space:]]*1([^0-9]|$)' || { echo "Mit .log erwartet: Dateien: 1. Ausgabe: $out"; exit 1; }
out=$(timeout 5 bash ./count_files.sh ./testdaten 2>&1)
echo "$out" | grep -Eq 'Dateien:[[:space:]]*8([^0-9]|$)' || { echo "Ohne Endung müssen weiterhin alle 8 Dateien gezählt werden."; exit 1; }
echo "Filter funktioniert."

out=$(timeout 5 bash ./log_analyzer.sh app.log ERROR 2>&1)
echo "$out" | grep -Eq 'ERROR:[[:space:]]*2([^0-9]|$)' || { echo "Für 'app.log ERROR' erwartet: ERROR: 2. Ausgabe: $out"; exit 1; }
echo "$out" | grep -Eq 'INFO|WARNING' && { echo "Mit Level ERROR sollen INFO und WARNING nicht ausgegeben werden."; exit 1; }
out=$(timeout 5 bash ./log_analyzer.sh app.log INFO 2>&1)
echo "$out" | grep -Eq 'INFO:[[:space:]]*6([^0-9]|$)' || { echo "Für 'app.log INFO' erwartet: INFO: 6. Ausgabe: $out"; exit 1; }
out=$(timeout 5 bash ./log_analyzer.sh app.log 2>&1)
echo "$out" | grep -Eq 'WARNING:[[:space:]]*2' || { echo "Ohne Level müssen weiterhin alle drei Werte kommen."; exit 1; }
echo "Filter funktioniert."
